const pjInputStyle='width:100%;min-height:38px;padding:8px 12px;border:1px solid var(--border-strong);border-radius:10px;background:var(--card);color:var(--fg);font:inherit';
let pjCurrent='p1', pjActiveTab=0, pjPreview='正常', pjReqTab=0, pjReqId='R-12', pjDispatchId='DP-8843', pjDispatchFilter='PROPOSED', pjWizard=null, pjNewItemProject='p1';
function pjEsc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function pjCap(p){return Number.isFinite(p.budget[1])?money(p.budget[1]):'不限';}
function pjIcons(){if(typeof lucide!=='undefined')lucide.createIcons({attrs:{'stroke-width':1.6}});}
function pjProject(id){return pjProjects.find(p=>p.id===id);}
function pjReadonly(p){return ['CLOSED','CANCELLED'].includes(p.stage)||!!p.archived;}
function pjButton(text,click,kind='',disabled=false,hint=''){return `<button type="button" class="btn ${kind}" onclick="${click}" ${disabled?'disabled':''}>${text}</button>${hint?`<span class="muted xs">${hint}</span>`:''}`;}
function pjField(label,id,value='',type='text',extra=''){return `<label class="stack small" style="gap:5px">${label}<input style="${pjInputStyle}" id="${id}" type="${type}" value="${pjEsc(value)}" ${extra}></label>`;}
function pjSelect(label,id,options,value){return `<label class="stack small" style="gap:5px">${label}<select style="${pjInputStyle}" id="${id}">${options.map(o=>`<option value="${pjEsc(o[0])}" ${o[0]===value?'selected':''}>${pjEsc(o[1])}</option>`).join('')}</select></label>`;}
function pjTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}"><div class="empty">暂无记录</div></td></tr>`}</tbody></table></div>`;}
function pjModal(title,body,footer,wide=false){openModal(`<div class="stack" style="padding:24px"><div class="row wrap"><h3 class="grow">${title}</h3>${pjButton('关闭','closeModal()','ghost sm')}</div>${body}<div id="pj-modal-error" role="alert" class="small" style="color:var(--danger)"></div><div class="row wrap" style="justify-content:flex-end">${footer}</div></div>`,wide);pjIcons();}
function pjError(message){const el=document.getElementById('pj-modal-error');if(el)el.textContent=message;else toast(message,'triangle-alert');}
function pjVal(id){const el=document.getElementById(id);return el?el.value.trim():'';}
function pjEvent(p,text){p.events.unshift(['刚刚','morgan',text]);p.version++;const original=PROJECTS.find(x=>x.id===p.id);if(original)Object.assign(original,{name:p.name,stage:p.stage,mode:p.mode,budget:[...p.budget],lead:p.lead,client:p.client});pjWork.filter(w=>w.p===p.id).forEach(w=>{const source=WI.find(x=>x.id===w.id);if(source)Object.assign(source,w);});}
function pjRefresh(){const el=document.getElementById('pj-project-body');if(el){el.innerHTML=pjProjectBody(pjProject(pjCurrent),pjActiveTab);pjIcons();}else route();}
function pjTabs(labels,index,fn){return `<div class="tabs row wrap">${labels.map((t,i)=>`<button type="button" class="${i===index?'on':''}" onclick="${fn}(this,${i})">${t}</button>`).join('')}</div>`;}
function pjTab(btn,index){pjActiveTab=index;btn.parentNode.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('on',i===index));pjRefresh();}
PAGES['project']=(id)=>{
 const p=pjProject(id);if(!p)return head('项目','项目不存在','你可以返回项目列表。',pjButton('返回项目',"go('projects')"));
 pjCurrent=id;pjActiveTab=0;pjNewItemProject=id;
 return head('项目 · '+p.code,p.name,`${TEAM.name} · 甲方开口：${p.client} · ${pjReadonly(p)?'项目已结束（只读）':'阶段由授权裁决推进'}`,`${S(p.mode)}${pjButton('设置','pjOpenTab(6)')}`)+pjTabs(['概览','需求','工作项','交付','团队','指标','设置'],0,'pjTab')+`<div id="pj-project-body">${pjProjectBody(p,0)}</div>`;
};
TITLES['project']='项目详情';NAVPARENT['project']='projects';
function pjOpenTab(index){const el=document.getElementById('pj-project-body');if(el){const tabs=el.previousElementSibling;pjTab(tabs.children[index],index);}}
function pjProjectBody(p,index){return [pjOverview,pjRequirementList,pjWorkList,pjDeliveryList,pjTeam,pjMetrics,pjSettings][index](p);}
function pjReadiness(p){
 const targets={INTAKE:'DISCOVERY',DISCOVERY:'PLANNING',PLANNING:'ACTIVE',ACTIVE:'ACCEPTANCE_PENDING',BLOCKED:'ACTIVE',ACCEPTANCE_PENDING:'DELIVERED',DELIVERED:'CLOSED'};
 const target=targets[p.stage];let checks=[];
 if(p.stage==='INTAKE')checks=[['至少一个关联来件或需求草稿',pjRequirements.some(r=>r.p===p.id)]];
 if(p.stage==='DISCOVERY')checks=[['所有在册需求已基线化并有验收标准',pjRequirements.some(r=>r.p===p.id)],['没有未结束的甲方澄清',p.id!=='p1']];
 if(p.stage==='PLANNING')checks=[['至少一个就绪工作项',pjWork.some(w=>w.p===p.id&&w.s==='READY')],['至少一名有执行权限的成员',p.members.some(k=>k==='chen'||PEOPLE[k].role==='Agent 执行者')],['全自治模式已设置预算上限',p.mode!=='AUTONOMOUS'||p.budget[1]>0]];
 if(p.stage==='ACTIVE')checks=[['至少一个交付包已发送',pjDeliveries.some(d=>d.p===p.id&&d.s==='SENT')]];
 if(p.stage==='BLOCKED')checks=[['需要填写解除阻塞说明',true]];
 if(p.stage==='ACCEPTANCE_PENDING')checks=[['全部可交付工作项已获甲方接受',pjDeliveries.filter(d=>d.p===p.id).every(d=>d.s==='ACCEPTED_D')],['没有待交付或待验收交付包',!pjDeliveries.some(d=>d.p===p.id&&['READY_D','SENT'].includes(d.s))],['没有未处理返工来件',p.id!=='p1']];
 if(p.stage==='DELIVERED')checks=[['没有未结束的工作项或执行',!pjWork.some(w=>w.p===p.id&&!['ACCEPTED','CANCELLED'].includes(w.s))]];
 return {target,checks,ready:!!target&&checks.every(c=>c[1])};
}
function pjOverview(p){const r=pjReadiness(p),pct=Number.isFinite(p.budget[1])?Math.round(p.budget[0]/p.budget[1]*100):0;
 return `<div class="grid g12"><div class="c12">${card('阶段与推进',`${stepper(p.stage)}<div class="row wrap" style="margin-top:16px">${r.target?pjButton('推进到 '+STAGE_ZH[r.target],`pjStage('${p.id}')`,r.ready?'primary':'',pjReadonly(p)):''}${!pjReadonly(p)?pjButton(p.stage==='BLOCKED'?'查看阻塞原因':'标记阻塞',`pjBlock('${p.id}')`,'',!['ACTIVE','BLOCKED'].includes(p.stage),'仅进行中的项目可标记阻塞'):''}</div><div class="stack small" style="margin-top:12px">${r.checks.map(c=>`<div class="row">${I(c[1]?'check':'x')}<span>${c[0]}</span>${S(c[1]?'PASSED':'INCONCLUSIVE',c[1]?'满足':'未满足')}</div>`).join('')}${p.stage==='BLOCKED'?`<div class="note warn">${pjEsc(p.blockReason)} · 类型：${pjEsc(p.blockKind)}</div>`:''}</div><div class="muted xs">你以交付负责人身份操作 · 权限来源 ROLE:delivery_lead。甲方验收前不能推进到已交付。</div>`,{icon:'flag'})}</div>
 <div class="c8 stack">${card('需求基线',`<dl class="kv"><dt>当前需求</dt><dd>${pjRequirements.filter(r=>r.p===p.id).length} 条</dd><dt>项目已接受</dt><dd>${p.acc[0]} / ${p.acc[1]} 项</dd><dt>待裁决</dt><dd>${pjWork.filter(w=>w.p===p.id&&w.s==='NEEDS_HUMAN_REVIEW').length} 项</dd></dl>${pjRequirementList(p)}`,{icon:'list-checks'})}
 ${card('风险',p.id==='p1'?`<div class="stack"><a href="#/workitem/BIL-139">${S('EXECUTION_FAILED','高')} BIL-139 第 3 次质量返工，需你关注</a><a href="#/workitem/BIL-145">${S('INCONCLUSIVE','中')} BIL-145 等待甲方澄清：财务角色是否含审计员</a><a href="#/delivery/D-2">${S('PARTIAL')} BIL#2 有拒收项，尚未完成交付闭环</a></div>`:p.id==='p2'?`<div class="note danger">预算使用 96.8%，升级规则已冻结委托，新执行暂停，等待所有者处理。</div>`:`<div class="note ok">${I('shield-check')}未发现需要你立即处理的风险。</div>`,{icon:'triangle-alert'})}
 ${card('近期活动',`<div class="stack">${p.events.concat(p.id==='p1'?[['09:31','morgan','接受 BIL-137，保留证据与裁决来源'],['09:02','lead','提出 BIL-143 派单，Morgan 确认'],['昨天 18:20','morgan','要求修改 BIL-139：按行项目舍入']]:[['今天','morgan','检查项目阶段与交付准备条件']]).slice(0,20).map(e=>`<div class="row wrap">${A(e[1])}<span class="muted xs">${e[0]}</span><span>${pjEsc(e[2])}</span></div>`).join('')}</div>`,{icon:'history'})}</div>
 <div class="c4 stack">${card('预算',`<div class="row wrap"><div class="ring" style="--p:${Math.min(100,pct)}"><div>${Number.isFinite(p.budget[1])?pct+'%':'不限'}</div></div><dl class="kv"><dt>已花费</dt><dd>${money(p.budget[0])}</dd><dt>预算上限</dt><dd>${pjCap(p)}</dd><dt>剩余</dt><dd>${Number.isFinite(p.budget[1])?money(Math.max(0,p.budget[1]-p.budget[0])):'不限'}</dd></dl></div><p class="muted small">80% 通知，100% 暂停新执行，不终止正在运行的执行。计入全部执行与返工成本。</p>${pjButton('调整预算',`pjBudget('${p.id}')`,'',pjReadonly(p))}`,{icon:'coins'})}
 ${card('团队模式',`${S(p.mode)}<p class="small">${p.mode==='HYBRID'?'人 + Agent 混编；有权限的主体负责裁决。':'全 Agent 也可执行；Agent 裁决仍需要有效且有范围的委托。'}</p><div class="stack small">${['预算','验证无定论','甲方拒收','返工上限'].map(x=>`<div>${I('check')} ${x}升级规则</div>`).join('')}</div><p class="muted xs">${p.mode==='AUTONOMOUS'?'3 条委托 · 最早 2 天 4 小时到期 · 当前因预算升级冻结':'尚无覆盖本项目、有效期 ≥24 小时的裁决委托'}</p>${pjButton(p.mode==='HYBRID'?'切换为全自治':'切回混编',`pjMode('${p.id}')`,'',pjReadonly(p))}${p.mode==='AUTONOMOUS'?pjButton('一键接管',`pjTakeover('${p.id}')`,'danger',pjReadonly(p)):''}`,{icon:'shield-half'})}
 ${pjOrchestration(p)}${card('交付摘要',`${pjDeliveries.filter(d=>d.p===p.id).map(d=>`<p><a href="#/delivery/${d.id}">${pjEsc(d.title)}</a> ${S(d.s)}</p>`).join('')||'<div class="empty">还没有交付包，先完成工作项验证与接受。</div>'}${pjButton('查看交付','pjOpenTab(3)','sm')}`,{icon:'package-check'})}</div></div>`;
}
function pjStage(id){const p=pjProject(id),r=pjReadiness(p);pjModal('推进阶段',`<p>${STAGE_ZH[p.stage]} → ${STAGE_ZH[r.target]||'无下一阶段'}</p>${r.checks.map(c=>`<div class="note ${c[1]?'ok':'warn'}">${I(c[1]?'check':'x')}${c[0]}</div>`).join('')}${pjField('推进理由（至少 10 个字）','pj-reason')}<div class="note info">你以交付负责人身份操作 · ROLE:delivery_lead。阶段不会根据工作项计数自动推进。</div>`,pjButton('取消','closeModal()')+pjButton('确认推进',`pjStageSave('${id}')`,'primary',!r.ready||pjReadonly(p),!r.ready?'先补齐以上守卫条件':''));}
function pjStageSave(id){const p=pjProject(id),r=pjReadiness(p);if(!r.ready||pjReadonly(p))return pjError('守卫条件未满足，无法推进。');const reason=pjVal('pj-reason');if(reason.length<10)return pjError('请填写至少 10 个字的理由。');p.stage=r.target;pjEvent(p,'推进至'+STAGE_ZH[p.stage]+'：'+reason);closeModal();route();toast('阶段已推进（原型演示）');}
function pjBlock(id){const p=pjProject(id);if(p.stage==='BLOCKED')return toast(p.blockReason,'triangle-alert');pjModal('标记项目阻塞',`${pjSelect('阻塞类型','pj-block-kind',[['CLIENT_CLARIFICATION','等待甲方澄清'],['DEPENDENCY','依赖'],['EXTERNAL','外部因素'],['OTHER','其他']],'CLIENT_CLARIFICATION')}${pjField('阻塞理由（至少 10 个字）','pj-reason')}<div class="note warn">阻塞后暂停自动派单与全自治新执行；等待甲方澄清时，门户显示「等待你的回复」。</div>`,pjButton('取消','closeModal()')+pjButton('确认阻塞',`pjBlockSave('${id}')`,'primary'));}
function pjBlockSave(id){const p=pjProject(id);if(p.stage!=='ACTIVE'||pjReadonly(p))return pjError('仅进行中的项目可以标记阻塞。');if(pjVal('pj-reason').length<10)return pjError('请填写至少 10 个字的理由。');p.blockReason=pjVal('pj-reason');p.blockKind=pjVal('pj-block-kind');p.stage='BLOCKED';pjEvent(p,'标记阻塞：'+p.blockReason);closeModal();route();}
function pjRequirementList(p){const list=pjRequirements.filter(r=>r.p===p.id);return list.length?pjTable(['需求基线','版本','优先级','验收标准','来源'],list.map(r=>`<tr><td><a href="#/requirement/${r.id}">${r.id} · ${pjEsc(r.title)}</a></td><td>${S('PASSED','已基线 v'+r.version)}</td><td>${r.priority}</td><td>${r.standards} 条</td><td>${r.source}</td></tr>`).join('')):`<div class="empty">还没有需求。你可以从来件转入需求。<div>${pjButton('从来件转入',"go('intakes')",'sm')}</div></div>`;}
function pjWorkList(p){return card('项目工作项',`<div class="row wrap" style="margin-bottom:12px">${pjSelect('筛选状态','pj-work-filter',[['','全部状态'],...['READY','CLAIMED','IN_PROGRESS','AGENT_CLAIMED_DONE','VERIFYING','NEEDS_HUMAN_REVIEW','ACCEPTED','REWORK','BLOCKED','EXECUTION_FAILED','CANCELLED'].map(s=>[s,({READY:'就绪',CLAIMED:'已认领',IN_PROGRESS:'进行中',AGENT_CLAIMED_DONE:'已声明完成（未验证）',VERIFYING:'验证中',NEEDS_HUMAN_REVIEW:'待裁决',ACCEPTED:'已接受',REWORK:'返工',BLOCKED:'阻塞',EXECUTION_FAILED:'执行失败',CANCELLED:'已取消'})[s]])],'')}${pjButton('筛选',`pjFilterWork('${p.id}')`,'sm')}${pjButton('新建工作项',`pjNewItemProject='${p.id}';newWorkItem()`,'primary',pjReadonly(p))}</div><div id="pj-work-table">${pjWorkRows(p,'')}</div><div class="muted xs">仅展示本项目工作项；接受必须逐项授权裁决，不能批量通过。</div>`,{icon:'kanban-square'});}
function pjWorkRows(p,state,req){const list=pjWork.filter(w=>w.p===p.id&&(!state||w.s===state)&&(!req||w.requirement===req));return pjTable(['编号与标题','状态','需求','类型 / 风险','估算','执行者','阶梯 / 覆盖','返工','基线 / 更新'],list.map(w=>`<tr><td><a href="#/workitem/${w.id}"><b>${w.id}</b><div>${pjEsc(w.t)}</div></a></td><td>${S(w.s)}</td><td>${w.requirement==='—'?'—':`<a href="#/requirement/${w.requirement}">${w.requirement}</a>`}</td><td>${pjType[w.type]} / ${pjRisk[w.risk]}</td><td>${w.estimate} 分钟</td><td>${who(w.who)}</td><td>${ladder(w.l)}<div class="muted xs">${w.s==='ACCEPTED'?'已接受标准关联见需求页':'未形成已接受覆盖'}</div></td><td>${w.s==='REWORK'?Math.max(0,w.br-1):0}</td><td>${w.baseline} ${w.stale?'<span class="badge b-warn">基线过期</span>':''}<div class="muted xs">演示快照</div></td></tr>`).join(''));}
function pjFilterWork(id){document.getElementById('pj-work-table').innerHTML=pjWorkRows(pjProject(id),pjVal('pj-work-filter'));pjIcons();}
function pjDeliveryList(p){return `<div class="stack">${card('项目交付列表',pjTable(['交付包','状态','交付项','验收结果','来源开口'],pjDeliveries.filter(d=>d.p===p.id).map(d=>`<tr><td><a href="#/delivery/${d.id}">${d.title}</a></td><td>${S(d.s)}</td><td>${d.count} 项</td><td>${d.result}</td><td>${d.source}</td></tr>`).join('')),{icon:'package-check'})}${card('交付资格',`<div class="note info">只有已接受工作项可以进入交付包；基线过期项须先重新裁决。正式交付只能由有权限的人重新认证后执行，不可委托。</div><div class="muted small">${p.id==='p1'?'BIL-137、BIL-135 为当前列表中的已接受工作项；BIL-142 仍待裁决。':'以完整项目接受记录为准，当前主文件仅提供部分工作项快照。'}</div>`)}${card('甲方验收',`<dl class="kv"><dt>验收期限</dt><dd>14 天</dd><dt>提醒</dt><dd>第 3、7、12 天；第 14 天升级</dd><dt>拒收后续</dt><dd>产生返工来件，保留原回执与交付证据</dd></dl>`)}</div>`;}
function pjOrchestration(p){return card('团队编排',`<dl class="kv"><dt>主管 Agent</dt><dd>${p.lead?who(p.lead):'未设置 — 系统评分，需你确认'}</dd><dt>运行时 / 模型</dt><dd class="small">${p.lead?PEOPLE[p.lead].model:'—'}</dd><dt>派单策略</dt><dd>${p.policy==='AUTO'&&p.lead?'策略内自动生效':'提案需人确认'}${p.policy==='AUTO'&&!p.lead?' · G9':''}</dd><dt>并行上限</dt><dd>${p.parallel} 枝（1–5）</dd><dt>近 24 小时</dt><dd>${p.id==='p1'?'3 提案 · 0 自动生效 · 1 改派 · 0 无合格候选':'暂无完整统计'}</dd></dl><div class="row wrap">${pjButton('编辑',`pjEditOrchestration('${p.id}')`,'sm',pjReadonly(p))}<a class="btn sm" href="#/dispatch/${p.id}">查看派单提案</a></div>`,{icon:'split'});}
function pjTeam(p){return `<div class="grid g12"><div class="c8">${card('项目成员与 Agent',pjTable(['成员','项目角色','来源','操作'],p.members.map(k=>{const busy=pjWork.some(w=>w.p===p.id&&w.who===k&&!['ACCEPTED','CANCELLED'].includes(w.s)),last=k==='morgan';return `<tr><td>${who(k)}</td><td>${PEOPLE[k].role}</td><td>${OR(k)||'人类成员'}</td><td>${pjButton('移除',`pjRemoveMember('${p.id}','${k}')`,'danger sm',pjReadonly(p)||busy||last,busy?'先改派活跃工作项':last?'最后一名交付负责人不可移除':'')}</td></tr>`;}).join(''))+`<div class="row wrap" style="margin-top:12px">${pjButton('添加成员',`pjAddMember('${p.id}')`,'primary',pjReadonly(p))}<span class="muted xs">委托请在授权与策略中授予；成员身份不授予 Agent 裁决权。</span></div>`,{icon:'users'})}</div><div class="c4 stack">${pjOrchestration(p)}${card('编制授权',`<p class="small">${p.id==='p1'?'Atlas · SG-3 · 在岗 2/3 · 今日创建 1/5 · $18.40 / $50.00':'主管只能在有效编制授权的名额与预算内创建子 Agent。'}</p><div class="note info">所有 Agent 保留人工创建、主管创建、已收编或孤儿来源。孤儿不能接新执行；成员添加不会创建 Agent。</div><a class="btn sm" href="#/policy">查看授权与策略</a>`,{icon:'id-card'})}</div></div>`;}
function pjAddMember(id){const p=pjProject(id),available=Object.keys(PEOPLE).filter(k=>PEOPLE[k].k!=='c'&&!p.members.includes(k));pjModal('添加项目成员',`${pjSelect('成员','pj-member',available.map(k=>[k,PEOPLE[k].n+' · '+PEOPLE[k].role]),available[0])}<div class="note info">按主体类型绑定项目角色。Agent 不可绑定人类交付负责人；孤儿仅可查看，不可接新执行。</div>`,pjButton('取消','closeModal()')+pjButton('添加',`pjAddMemberSave('${id}')`,'primary',!available.length,!available.length?'所有团队成员已在项目中':''));}
function pjAddMemberSave(id){const p=pjProject(id),k=pjVal('pj-member');if(pjReadonly(p)||!PEOPLE[k]||PEOPLE[k].k==='c'||p.members.includes(k))return pjError('无法添加该成员。');p.members.push(k);pjEvent(p,'添加项目成员 '+PEOPLE[k].n);closeModal();pjRefresh();}
function pjRemoveMember(id,k){const p=pjProject(id);if(pjReadonly(p)||k==='morgan'||pjWork.some(w=>w.p===id&&w.who===k&&!['ACCEPTED','CANCELLED'].includes(w.s)))return toast('请先改派；最后一名交付负责人不可移除。');pjModal('移除项目成员',`<div class="note danger">将移除 ${PEOPLE[k].n} 的项目角色绑定，保留历史工作与审计；不会删除团队成员或 Agent。</div>`,pjButton('取消','closeModal()')+pjButton('确认移除',`pjRemoveMemberSave('${id}','${k}')`,'danger'));}
function pjRemoveMemberSave(id,k){const p=pjProject(id);if(pjReadonly(p)||k==='morgan'||pjWork.some(w=>w.p===id&&w.who===k&&!['ACCEPTED','CANCELLED'].includes(w.s)))return pjError('成员仍有活跃分派，请先改派。');p.members=p.members.filter(x=>x!==k);pjEvent(p,'移除项目成员 '+PEOPLE[k].n);closeModal();pjRefresh();}
function pjEditOrchestration(id){const p=pjProject(id);pjModal('编辑团队编排',`${pjSelect('主管 Agent','pj-lead',[['','未设置'],...p.members.filter(k=>PEOPLE[k].role==='主管 Agent').map(k=>[k,PEOPLE[k].n])],p.lead||'')}${pjSelect('派单策略','pj-policy',[['MANUAL','提案需人确认'],['AUTO','策略内自动生效'] ],p.policy)}${pjField('并行上限（1–5）','pj-parallel',p.parallel,'number','min="1" max="5"')}<div class="note info">仅列出本项目有主管角色绑定的运行中 Agent。自动策略无主管时按人工确认处理（G9）；护栏 G1–G9 命中仍需你确认。</div>`,pjButton('取消','closeModal()')+pjButton('保存',`pjSaveOrchestration('${id}')`,'primary'));}
function pjSaveOrchestration(id){const p=pjProject(id),n=Number(pjVal('pj-parallel'));if(pjReadonly(p))return pjError('项目只读。');if(!Number.isInteger(n)||n<1||n>5)return pjError('并行上限必须是 1–5 的整数。');p.lead=pjVal('pj-lead')||null;p.policy=pjVal('pj-policy');p.parallel=n;pjEvent(p,'更新团队编排');closeModal();pjRefresh();toast(p.policy==='AUTO'&&!p.lead?'已保存；无主管，仍需人工确认':'团队编排已保存（演示）');}
function pjMetrics(p){return `<div class="row wrap" style="margin-bottom:12px">${pjSelect('统计窗口','pj-metric-window',[['7','近 7 天'],['30','近 30 天'],['90','近 90 天']],'30')}${pjButton('应用窗口',`pjMetricWindow('${p.id}')`,'sm')}<span class="muted xs">含今天的未定稿数据；趋势为演示快照。</span></div><div id="pj-metric-body">${pjMetricTiles(p,30)}</div>`;}
function pjMetricTiles(p,days){const n=p.acc[0],has=n>0,first=Math.floor(n*.73),attention=n*10;const tiles=[['每个已接受交付物成本',has?money(p.budget[0]/n):'—',`${money(p.budget[0])} / ${n} 项`,'窗口全部执行成本 ÷ 首次已接受工作项数；返工成本计入、再次接受不重复计数。'],['首次验收率',has?(first/n*100).toFixed(1)+'%':'—',`${first} / ${n}`,'首次接受前没有拒绝、要求修改或质量返工的工作项数 ÷ 首次已接受工作项数。'],['人工关注分钟 / 交付物',has?'10.0 分钟':'—',`共 ${attention} 分钟`,'人工关注毫秒 ÷ 60000 ÷ 首次已接受工作项数。'],['返工周期',has?'均值 9.0 小时':'—',has?'P50 ≤4 小时 · P90 ≤48 小时 · 4 次':'暂无闭合周期','拒绝或要求修改（含甲方拒收）至下一次接受的闭合周期；均值为总时长 ÷ 周期数。'],['证据覆盖率',has?'94.4%':'—',has?'17 / 18 · 标准覆盖 88.0%':'暂无声明','具有可审查证据的声明工作项数 ÷ 声明工作项数；证据须有内容哈希，Agent 观察不计入。']];return `<div class="grid g12">${tiles.map((t,i)=>`<div class="c4">${card(t[0],`<div class="kpi"><b>${t[1]}</b></div><div class="muted small">${has?t[2]:'暂无数据'}</div>${has?`<div class="small">${i===0?'较上一同长窗口 ↓ 8%':'较上一同长窗口改善'}</div>${spark([12,18,15,23,27,25,31])}`:''}<details><summary class="small">公式与窗口</summary><p class="muted small">${t[3]}窗口：近 ${days} 天。</p></details>`)}</div>`).join('')}<div class="c12">${card('甲方一次验收与日趋势',`<dl class="kv"><dt>甲方一次验收率</dt><dd>${p.id==='p1'?'50.0% · 1 / 2':p.id==='p2'||p.id==='p3'?'— · 暂无已收到回执':'— · 暂无数据'}</dd><dt>公式</dt><dd>结果为全部接受的首份回执数 / 首份回执总数；部分验收与拒收只计分母。</dd></dl><p class="muted xs">近 ${days} 天 · 模拟趋势仅展示图形，不替代真实统计。</p>${has?spark([16,20,18,24,22,28,30]):'<div class="empty">没有可计算的日序列。</div>'}`)}</div></div>`;}
function pjMetricWindow(id){const el=document.getElementById('pj-metric-body');el.innerHTML=pjMetricTiles(pjProject(id),Number(pjVal('pj-metric-window')));pjIcons();}
function pjSettings(p){const ro=pjReadonly(p);return `<div class="grid g12"><div class="c6 stack">${card('基本信息',`${pjField('项目名称','pj-name',p.name,'text','maxlength="200" '+(ro?'disabled':''))}${pjField('代号（创建后不可修改）','pj-code',p.code,'text','readonly')}${pjField('简介','pj-description',p.description,'text','maxlength="2000" '+(ro?'disabled':''))}${pjField('目标交付日','pj-target',p.target,'date',ro?'disabled':'')}${pjButton('保存基本信息',`pjSaveSettings('${p.id}')`,'primary',ro)}`,{icon:'settings'})}
 ${card('开口与联系人',`<dl class="kv"><dt>发送开口</dt><dd>${p.client}</dd><dt>主联系人</dt><dd>${p.contacts?pjEsc(p.client):'尚未配置'}</dd><dt>接收交付 / 签收</dt><dd>${p.contacts?'主联系人接收交付，且可签收':'没有可签收联系人将无法正式交付'}</dd></dl>${pjButton(p.contacts?'移除联系人':'添加联系人',`pjContact('${p.id}')`,p.contacts?'danger sm':'sm',ro||(p.contacts&&pjDeliveries.some(d=>d.p===p.id&&d.s==='SENT')),p.contacts&&pjDeliveries.some(d=>d.p===p.id&&d.s==='SENT')?'有待验收交付，不能删除最后可签收联系人':'')}`,{icon:'contact'})}
 ${card('预算与事件',`<dl class="kv"><dt>预算上限</dt><dd>${pjCap(p)}</dd><dt>通知阈值</dt><dd>${p.notify||80}%（50–95）</dd><dt>耗尽策略</dt><dd>100% 暂停，不可调整</dd></dl>${pjButton('调整预算上限',`pjBudget('${p.id}')`,'',ro)}<p class="muted xs">仅有项目管理权限的人可调整，需重新认证。</p>${pjTable(['预算事件','说明'],(p.budgetEvents||[]).map(e=>`<tr><td>上限变更</td><td>${pjEsc(e)}</td></tr>`).join(''))}`,{icon:'coins'})}</div>
 <div class="c6 stack">${card('门户可见性',`<div class="stack">${[['ai','AI 参与展示'],['titles','工作项标题'],['evidence','证据摘要'],['notes','发布说明'],['milestones','里程碑']].map(([k,t])=>`<label class="row"><input type="checkbox" id="pj-portal-${k}" ${(k==='ai'?p.ai:p.portal[k])?'checked':''} ${ro?'disabled':''} onchange="pjPortalPreview('${p.id}')">${t}</label>`).join('')}${pjSelect('贡献者展示','pj-contributors',[['TEAM_ONLY','只显示团队品牌'],['ROLES','显示工程师 / AI 成员角色，不显示姓名']],p.roles?'ROLES':'TEAM_ONLY').replace('<select ',`<select onchange="pjPortalPreview('${p.id}')" ${ro?'disabled':''} `)}<div id="pj-portal-preview">${pjPortalText(p)}</div>${pjButton('保存门户可见性',`pjSavePortal('${p.id}')`,'primary',ro)}</div>`,{icon:'eye'})}
 ${card('仓库与验收策略',`<dl class="kv"><dt>主仓库</dt><dd class="code">${p.repo?pjEsc(p.repo):p.code.toLowerCase()+' · main'}</dd><dt>仓库规则</dt><dd>远程地址不得包含凭证；机器上的本地路径在机器页配置。</dd><dt>验收期限</dt><dd>14 天</dd><dt>提醒 / 升级</dt><dd>第 3、7、12 天提醒，第 14 天升级</dd></dl><label class="row"><input type="checkbox" disabled>逾期视同验收</label><p class="muted xs">当前版本不支持：验收只能来自甲方。</p>`,{icon:'git-branch'})}
 ${card('危险区',`<div class="note danger">取消将取消未结束工作项、停止活跃执行、撤销本项目委托；归档隐藏项目列表入口，保留历史。危险操作需重新认证。</div><div class="row wrap">${pjButton('归档项目',`pjDanger('${p.id}','archive')`,'danger',!['CLOSED','CANCELLED'].includes(p.stage)||!!p.archived,'仅已关闭或已取消的项目可以归档')}${pjButton('取消项目',`pjDanger('${p.id}','cancel')`,'danger',ro)}</div>`,{icon:'triangle-alert'})}</div></div>`;}
function pjSaveSettings(id){const p=pjProject(id),name=pjVal('pj-name');if(pjReadonly(p))return toast('项目只读');if(!name||name.length>200)return toast('名称必填，最多 200 字');if(pjProjects.some(x=>x.id!==id&&x.client===p.client&&x.name===name))return toast('同甲方下已存在同名项目');p.name=name;p.description=pjVal('pj-description');p.target=pjVal('pj-target');pjEvent(p,'更新项目基本信息');toast('已保存基本信息（演示）');}
function pjContact(id){const p=pjProject(id);if(pjReadonly(p)||p.contacts&&pjDeliveries.some(d=>d.p===id&&d.s==='SENT'))return toast('待验收交付需要保留可签收联系人。');pjModal(p.contacts?'移除联系人':'添加联系人',`<div class="note ${p.contacts?'danger':'info'}">${p.contacts?'移除后没有可签收联系人，无法正式交付；保留历史回执。':'使用本项目来源开口联系人作为主联系人，默认接收交付且可签收。'}</div><p>${p.client}</p>`,pjButton('取消','closeModal()')+pjButton('确认',`pjContactSave('${id}')`,p.contacts?'danger':'primary'));}
function pjContactSave(id){const p=pjProject(id);if(pjReadonly(p)||p.contacts&&pjDeliveries.some(d=>d.p===id&&d.s==='SENT'))return pjError('不能移除最后可签收联系人。');p.contacts=!p.contacts;pjEvent(p,'更新甲方联系人');closeModal();pjRefresh();}
function pjPortalText(p){return `<div class="note info"><div><b>甲方预览 · ${TEAM.name}</b><p>${p.ai?'由 AI 与工程师协作完成':'项目交付由团队负责'}</p><span class="small">${p.roles?'展示角色：工程师 / AI 成员':'只展示团队品牌'} · ${p.portal.evidence?'展示证据摘要':'隐藏证据摘要'}</span></div></div>`;}
function pjPortalPreview(id){const p=pjProject(id),copy={...p,ai:document.getElementById('pj-portal-ai').checked,portal:{...p.portal}};['titles','evidence','notes','milestones'].forEach(k=>copy.portal[k]=document.getElementById('pj-portal-'+k).checked);copy.roles=pjVal('pj-contributors')==='ROLES';document.getElementById('pj-portal-preview').innerHTML=pjPortalText(copy);}
function pjSavePortal(id){const p=pjProject(id);if(pjReadonly(p))return toast('项目只读');p.ai=document.getElementById('pj-portal-ai').checked;['titles','evidence','notes','milestones'].forEach(k=>p.portal[k]=document.getElementById('pj-portal-'+k).checked);p.roles=pjVal('pj-contributors')==='ROLES';pjPortalPreview(id);pjEvent(p,'保存门户可见性');toast('门户可见性已保存（演示）');}
function pjStepup(action){return `<div class="note warn">${I('fingerprint')}需重新认证。原型仅模拟身份验证，不会进行真实认证或调用服务。</div><label class="row"><input type="checkbox" id="pj-stepup">你已完成重新认证（演示） · ${action}</label>`;}
function pjBudget(id){const p=pjProject(id);pjModal('调整预算上限',`${pjField('预算上限（美元，两位小数）','pj-cap',Number.isFinite(p.budget[1])?p.budget[1].toFixed(2):'','number','min="0.01" step="0.01"')}${pjField('通知阈值（50–95）','pj-notify',p.notify||80,'number','min="50" max="95"')}${pjField('修改理由','pj-reason')}<p class="small">当前已花费 ${money(p.budget[0])}。降低到已花费以下将暂停新执行；提高上限只解除预算暂停，不解除其他升级暂停。</p>${pjStepup('预算上限修改')}`,pjButton('取消','closeModal()')+pjButton('验证身份并保存',`pjBudgetSave('${id}')`,'primary'));}
function pjBudgetSave(id){const p=pjProject(id),cap=Number(pjVal('pj-cap')),n=Number(pjVal('pj-notify'));if(pjReadonly(p))return pjError('项目只读。');if(!/^\d+(\.\d{1,2})?$/.test(pjVal('pj-cap'))||!Number.isFinite(cap)||cap<=0||!Number.isInteger(n)||n<50||n>95)return pjError('预算须大于零且最多两位小数，通知阈值须为 50–95 的整数。');if(!pjVal('pj-reason'))return pjError('请填写预算修改理由。');if(!document.getElementById('pj-stepup').checked)return pjError('需先完成重新认证（演示）。');p.budgetEvents=p.budgetEvents||[];p.budgetEvents.unshift(money(p.budget[1])+' → '+money(cap)+' · '+pjVal('pj-reason'));p.budget[1]=cap;p.notify=n;pjEvent(p,'调整预算上限为 '+money(cap));closeModal();pjRefresh();toast('预算已保存；其他暂停原因保持有效');}
function pjMode(id){const p=pjProject(id),hybrid=p.mode==='HYBRID',checks=[['P1','至少一条覆盖项目的有效裁决委托，受托评审 Agent 运行中，剩余 ≥24 小时',!hybrid],['P2','预算、验证无定论、甲方拒收、返工上限四类升级规则已启用',true],['P3','预算上限已设置且未耗尽',p.budget[1]>p.budget[0]],['P4','至少一名有项目执行角色的运行中 Agent',p.members.some(k=>PEOPLE[k].role==='Agent 执行者'&&PEOPLE[k].origin!=='orphan')],['P5','阶段为规划中、进行中或待验收',['PLANNING','ACTIVE','ACCEPTANCE_PENDING'].includes(p.stage)]];pjModal(hybrid?'切换为全自治':'切回混编',`${hybrid?checks.map(c=>`<div class="note ${c[2]?'ok':'warn'}">${c[0]} · ${c[1]} · ${c[2]?'通过':'未满足'}</div>`).join(''):'<div class="note danger">将撤销本项目 Agent 裁决委托，改为人工确认；正在运行的执行不会因此强制终止。</div>'}${pjField('切换理由（至少 10 个字）','pj-reason')}${pjStepup('团队模式切换')}`,pjButton('取消','closeModal()')+pjButton('验证身份并切换',`pjModeSave('${id}')`,hybrid?'primary':'danger',pjReadonly(p)||hybrid&&!checks.every(c=>c[2]),hybrid?'当前项目尚无符合 P1 的裁决委托，请在授权与策略中授予后再切换':''));}
function pjModeSave(id){const p=pjProject(id);if(pjReadonly(p)||p.mode==='HYBRID')return pjError('全自治前置条件未满足。');if(pjVal('pj-reason').length<10||!document.getElementById('pj-stepup').checked)return pjError('请填写至少 10 个字的理由，并完成重新认证。');p.mode='HYBRID';p.policy='MANUAL';pjEvent(p,'切回混编，撤销项目 Agent 裁决委托');closeModal();route();}
function pjTakeover(id){pjModal('一键接管',`<div class="note danger">撤销本项目全部 Agent 裁决委托，切回混编与人工派单，保留执行记录。主管创建的 Agent 不会因此被删除；编制授权须单独管理。</div>${pjField('接管理由（至少 10 个字）','pj-reason')}${pjStepup('接管')}`,pjButton('取消','closeModal()')+pjButton('验证身份并接管',`pjModeSave('${id}')`,'danger'));}
function pjDanger(id,kind){const p=pjProject(id),cancel=kind==='cancel',count=pjWork.filter(w=>w.p===id&&!['ACCEPTED','CANCELLED'].includes(w.s)).length;pjModal(cancel?'取消项目':'归档项目',`<div class="note danger">${cancel?`将取消 ${count} 个未结束工作项，停止关联活跃执行，撤销本项目委托；保留已经接受的工作与历史证据。`:'将从默认项目列表隐藏项目，所有历史资料保持只读。'}操作将留下审计记录。</div>${pjField('输入项目代号 '+p.code+' 确认','pj-confirm')}${pjField('操作理由（至少 10 个字）','pj-reason')}${pjStepup(cancel?'取消项目':'归档项目')}`,pjButton('返回','closeModal()')+pjButton('验证身份并'+(cancel?'取消':'归档'),`pjDangerSave('${id}','${kind}')`,'danger'));}
function pjDangerSave(id,kind){const p=pjProject(id);if(kind==='archive'&&!['CLOSED','CANCELLED'].includes(p.stage)||kind==='cancel'&&pjReadonly(p))return pjError('当前阶段不允许此操作。');if(pjVal('pj-confirm')!==p.code||pjVal('pj-reason').length<10||!document.getElementById('pj-stepup').checked)return pjError('请正确输入代号、至少 10 个字的理由，并完成重新认证。');if(kind==='cancel'){p.stage='CANCELLED';pjWork.filter(w=>w.p===id&&!['ACCEPTED','CANCELLED'].includes(w.s)).forEach(w=>w.s='CANCELLED');}else p.archived=true;pjEvent(p,kind==='cancel'?'取消项目':'归档项目');closeModal();route();toast('已完成（原型演示，刷新恢复）');}

/* 需求基线与范围变更 */
PAGES['requirement']=(id)=>{const r=pjRequirements.find(x=>x.id===id);if(!r)return head('需求','需求不存在','当前原型尚未包含这条需求。',pjButton('返回项目',"go('projects')"));pjReqId=id;pjReqTab=0;pjPreview='正常';return head('项目需求 · '+id,r.title,`${TEAM.name} · 当前基线 v${r.version} · 修改必须发起范围变更`,pjButton('返回项目',`go('project/${r.p}')`)+pjButton('发起范围变更',`pjScope('${id}')`,'danger',id!=='R-12'||pjReadonly(pjProject(r.p)),id!=='R-12'?'当前演示仅提供 R-12 的标准明细':''))+pjTabs(['基线与验收标准','版本时间线与对比','关联工作项'],0,'pjRequirementTab')+`<div class="row wrap" style="margin:12px 0"><span class="muted small">状态预览</span>${['正常','空','错误','无权限'].map(s=>`<button class="chip ${s===pjPreview?'on':''}" type="button" onclick="pjPreviewSet(this,'${s}')">${s}</button>`).join('')}</div><div id="pj-requirement-body">${pjRequirementBody()}</div>`;};
TITLES['requirement']='需求详情';NAVPARENT['requirement']='projects';
function pjRequirementTab(btn,index){pjReqTab=index;btn.parentNode.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('on',i===index));pjReqRefresh();}
function pjPreviewSet(btn,state){pjPreview=state;btn.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.textContent===state));pjReqRefresh();}
function pjReqRefresh(){const el=document.getElementById('pj-requirement-body');if(el){el.innerHTML=pjRequirementBody();pjIcons();}}
function pjCoverage(c){return c.items.some(id=>pjWork.find(w=>w.id===id&&w.s==='ACCEPTED'&&!w.stale));}
function pjRequirementBody(){const r=pjRequirements.find(x=>x.id===pjReqId),p=pjProject(r.p);if(pjPreview==='空')return card('需求基线','<div class="empty">还没有验收标准。你可以在草稿阶段补充标准，再基线化。</div>');if(pjPreview==='错误')return card('读取失败',`<div class="note danger">暂时无法读取需求基线，你的修改没有提交。</div>${pjButton('重试',"route()",'primary')}`);if(pjPreview==='无权限')return card('访问受限','<div class="note warn">你没有查看此需求的权限，请联系项目交付负责人。</div>');if(r.id!=='R-12')return `<div class="stack">${card('需求基线',`<dl class="kv"><dt>版本</dt><dd>v${r.version}</dd><dt>验收标准</dt><dd>${r.standards} 条</dd><dt>优先级</dt><dd>${r.priority}</dd></dl>`)}${card('关联工作项',pjWorkRows(p,'').replace('项目工作项','关联工作项'))}${card('来源来件',`<a href="#/intake/${r.intake}">${r.intake} · ${r.source}</a><p class="muted small">主文件未提供这条需求的逐条验收标准，不编造内容。</p>`)}</div>`;
 if(pjReqTab===1)return pjVersionView(r);
 if(pjReqTab===2)return `<div class="stack">${card('关联工作项',pjTable(['工作项','状态','基线','关联标准'],pjWork.filter(w=>w.requirement===r.id).map(w=>`<tr><td><a href="#/workitem/${w.id}">${w.id} · ${pjEsc(w.t)}</a></td><td>${S(w.s)}</td><td>${w.baseline} ${w.stale?'<span class="badge b-warn">基线过期</span>':''}</td><td>${pjCriteria.filter(c=>c.items.includes(w.id)).map(c=>c.code).join('、')||'未关联'}</td></tr>`).join('')))}${card('过期基线处理','<div class="note warn">被范围变更标记过期的工作项必须重新对照当前验收标准验证、裁决，不能直接进入交付包。</div>')}${card('来源与拆解','<p>这些工作项属于同一需求基线；依赖应保留在同项目内。验收标准覆盖由已接受工作项决定。</p>')}</div>`;
 return `<div class="grid g12"><div class="c8 stack">${card('基线描述',`<p>${pjEsc(r.description||'财务人员按账期导出 CSV，字段与甲方模板一致，金额按行项目舍入，失败时提供重试提示。')}</p><div class="note info">已基线 v${r.version}，只读。修改需发起范围变更；Agent 声明完成不代表标准已被覆盖。</div>`)}${card('验收标准',pjTable(['标准','内容','必需 / 引入','关联工作项','覆盖状态'],pjCriteria.map(c=>`<tr><td class="mono">${c.code}</td><td>${pjEsc(c.text)}</td><td>是 · v${c.since}</td><td>${c.items.map(id=>`<a href="#/workitem/${id}">${id}</a>`).join('<br>')}</td><td>${S(pjCoverage(c)?'PASSED':c.items.length?'IN_PROGRESS':'PENDING',pjCoverage(c)?'已被接受工作项覆盖':c.items.length?'进行中':'无工作项')}</td></tr>`).join('')),{icon:'list-checks'})}</div><div class="c4 stack">${card('覆盖率',`<b>${(pjCriteria.filter(pjCoverage).length/pjCriteria.length*100).toFixed(1)}%</b><p>${pjCriteria.filter(pjCoverage).length} / ${pjCriteria.length} 条必需标准被已接受工作项覆盖</p><div class="progress"><i style="width:${pjCriteria.filter(pjCoverage).length/pjCriteria.length*100}%"></i></div><p class="muted xs">这里只计算验收标准覆盖，不是证据覆盖或项目工作项接受率。</p>`)}${card('来源来件',`<a href="#/intake/${r.intake}">${r.intake} · ${r.source}</a><dl class="kv"><dt>甲方联系人</dt><dd>${who('lee')}</dd><dt>开口</dt><dd>门户</dd><dt>关联项目</dt><dd><a href="#/project/p1">账单中心</a></dd></dl>`)}${card('授权边界','<div class="note warn">范围变更只能由有范围变更权限的人重新认证后提交，不可委托给 Agent。</div>')}</div></div>`;
}
function pjScope(id){const r=pjRequirements.find(x=>x.id===id);if(id!=='R-12'||pjReadonly(pjProject(r.p)))return toast('当前需求不可发起演示范围变更');pjModal('发起范围变更 · 基于 v'+r.version,`<div class="grid g12"><div class="c6 stack">${pjField('需求标题','pj-scope-title',r.title)}${pjField('描述','pj-scope-description',r.description)}${pjSelect('优先级','pj-scope-priority',[['高','高'],['中','中'],['低','低']],r.priority)}${pjSelect('标准修改方式','pj-scope-kind',[['add','新增'],['retire','退役'],['rewrite','改写（替换）']],'rewrite')}${pjSelect('受影响标准','pj-scope-criterion',pjCriteria.map(c=>[c.code,c.code+' · '+c.text]),'C7')}${pjField('新增 / 改写后的标准文本','pj-scope-text','金额显示币种并保留两位小数')}${pjButton('计算影响预览','pjScopePreview()','sm')}</div><div class="c6 stack"><div id="pj-scope-impact">${pjScopeImpact('C7','rewrite')}</div>${pjField('变更摘要（必填）','pj-scope-summary')}${pjField('理由（必填）','pj-reason')}${pjField('来源来件（可选）','pj-scope-source',r.intake)}${pjStepup('范围变更')}<div class="note danger">新基线将使受影响工作项过期，或按你的选择取消；取消会停止该项执行，证据与审计保留。提交需重新认证。</div></div></div>`,pjButton('取消','closeModal()')+pjButton('验证身份并提交',`pjScopeSave(${r.version})`,'danger'),true);}
function pjScopeImpact(code,kind){const c=pjCriteria.find(c=>c.code===code),ids=kind==='add'?[]:c?c.items:[];return `<b>影响预览</b><div id="pj-impact-meta" data-code="${code}" data-kind="${kind}"></div>${ids.length?ids.map(id=>`${pjSelect(id+' · '+pjWork.find(w=>w.id===id).t,'pj-impact-'+id,[['stale','标记过期'],...(!['ACCEPTED','CANCELLED'].includes(pjWork.find(w=>w.id===id).s)?[['cancel','取消']]:[])],'stale')}${pjWork.find(w=>w.id===id).s==='ACCEPTED'?'<span class="muted xs">已接受工作项只标记过期，不改变状态；新范围须新建工作项或走返工来件。</span>':''}`).join(''):'<div class="note info">新增标准暂无关联工作项，覆盖状态为「无工作项」。</div>'}<p class="muted xs">退役与改写只影响该标准关联的工作项；每个受影响项必须逐项选择。</p>`;}
function pjScopePreview(){document.getElementById('pj-scope-impact').innerHTML=pjScopeImpact(pjVal('pj-scope-criterion'),pjVal('pj-scope-kind'));}
function pjVersionView(r){const versions=pjVersions.map(v=>[String(v.version),'v'+v.version]);return `<div class="grid g12"><div class="c4">${card('基线版本时间线',`<div class="stack">${[...pjVersions].reverse().map(v=>`<div><b>v${v.version} · ${v.at}</b><p class="small">${v.criteria.length} 条生效标准 · ${pjEsc(v.title)}</p><a href="#/audit">${v.record} · Morgan 授权裁决</a></div>`).join('')}</div>`,{icon:'history'})}</div><div class="c8 stack">${card('版本对比',`<div class="row wrap">${pjSelect('旧版本','pj-version-old',versions,String(Math.max(1,r.version-1)))}${pjSelect('新版本','pj-version-new',versions,String(r.version))}${pjButton('对比','pjCompareVersions()','primary sm')}</div><div id="pj-version-diff">${pjVersionDiff(Math.max(1,r.version-1),r.version)}</div>`,{icon:'git-compare'})}${card('版本影响','<p>退役标准保留在历史基线中；改写通过新增替换标准表达。受影响工作项必须重新验证与裁决，不能静默沿用旧基线。</p>')}</div></div>`;}
function pjVersionDiff(from,to){const a=pjVersions.find(v=>v.version===Number(from)),b=pjVersions.find(v=>v.version===Number(to));if(!a||!b)return '<div class="note warn">请选择有效版本。</div>';const added=b.criteria.filter(c=>!a.criteria.some(old=>old.code===c.code)),retired=a.criteria.filter(c=>!b.criteria.some(next=>next.code===c.code));return `<h3>v${a.version} → v${b.version}</h3><div class="note info">标题：${pjEsc(a.title)} → ${pjEsc(b.title)}</div><div class="note info">描述：<p>${pjEsc(a.description)}</p><p>${pjEsc(b.description)}</p></div>${retired.map(c=>`<div class="note danger"><s>退役 ${c.code}：${pjEsc(c.text)}</s></div>`).join('')}${added.map(c=>`<div class="note ok">新增 ${c.code}：${pjEsc(c.text)}</div>`).join('')}${a.version===3&&b.version===4?'<div class="note warn">改写 C3 → C7：金额保留两位小数，按行项目舍入。新增 C8：文件名包含账期。</div>':''}${!added.length&&!retired.length?'<p class="muted small">没有验收标准变化。</p>':''}`;}
function pjCompareVersions(){document.getElementById('pj-version-diff').innerHTML=pjVersionDiff(pjVal('pj-version-old'),pjVal('pj-version-new'));pjIcons();}
function pjScopeSave(version){const r=pjRequirements.find(x=>x.id==='R-12'),p=pjProject(r.p),kind=pjVal('pj-scope-kind'),code=pjVal('pj-scope-criterion'),meta=document.getElementById('pj-impact-meta');if(pjReadonly(p))return pjError('项目只读。');if(r.version!==version)return pjError('需求已被他人更新到 v'+r.version+'，请关闭、刷新后重做（120440）。');if(!pjVal('pj-scope-title')||!pjVal('pj-scope-summary')||!pjVal('pj-reason')||(kind!=='retire'&&!pjVal('pj-scope-text')))return pjError('请填写标题、摘要、理由与标准文本。');if(meta.dataset.code!==code||meta.dataset.kind!==kind)return pjError('标准或修改方式已变化，请重新计算影响预览。');if(!document.getElementById('pj-stepup').checked)return pjError('请先完成重新认证（演示）。');const index=pjCriteria.findIndex(c=>c.code===code),old=pjCriteria[index],items=kind==='add'?[]:[...old.items];items.forEach(id=>{const w=pjWork.find(x=>x.id===id);if(pjVal('pj-impact-'+id)==='cancel'&&!['ACCEPTED','CANCELLED'].includes(w.s))w.s='CANCELLED';else w.stale=true;});r.version++;r.title=pjVal('pj-scope-title');r.description=pjVal('pj-scope-description');r.priority=pjVal('pj-scope-priority');if(kind==='retire'||kind==='rewrite')pjCriteria.splice(index,1);if(kind!=='retire')pjCriteria.push({code:'C'+(Math.max(8,...pjCriteria.map(c=>Number(c.code.slice(1))))+1),text:pjVal('pj-scope-text'),since:r.version,items:kind==='rewrite'?items:[]});r.standards=pjCriteria.length;pjVersions.push({version:r.version,at:'刚刚',title:r.title,description:r.description,criteria:pjCriteria.map(c=>({...c,items:[...c.items]})),record:'CH-演示-'+r.version});pjEvent(p,'范围变更至 v'+r.version+'：'+pjVal('pj-scope-summary'));closeModal();route();toast('新基线已生成，受影响工作项已处理（演示）');}

/* 派单提案 */
PAGES['dispatch']=(id)=>{const p=pjProject(id);if(!p)return head('派单','项目不存在','你可以返回项目列表。');pjCurrent=id;pjDispatchFilter='PROPOSED';const first=pjProposals.find(q=>q.p===id&&q.state==='PROPOSED');pjDispatchId=first?first.id:'';return head('项目编排 · '+p.code,'派单提案',`${TEAM.name} · ${p.policy==='AUTO'?'策略内自动生效，护栏命中需你确认':'主管提出建议，由你确认'}`,pjButton('返回项目',`go('project/${id}')`))+`<div id="pj-dispatch-body">${pjDispatchBody(p)}</div>`;};
TITLES['dispatch']='派单提案';NAVPARENT['dispatch']='projects';
function pjProposalState(q){return q.state==='PROPOSED'&&q.expires<=Date.now()?'EXPIRED':q.state;}
function pjDispatchBody(p){const labels={PROPOSED:'待处理',APPLIED:'已生效',OVERRIDDEN:'已改派',REJECTED:'已驳回',EXPIRED:'已过期'};const list=pjProposals.filter(q=>q.p===p.id&&pjProposalState(q)===pjDispatchFilter).sort((a,b)=>(a.expires||0)-(b.expires||0));const q=list.find(q=>q.id===pjDispatchId)||list[0];if(q)pjDispatchId=q.id;return `<div class="grid g12"><div class="c4 stack">${card('提案列表',`<div class="row wrap">${Object.keys(labels).map(k=>`<button class="chip ${pjDispatchFilter===k?'on':''}" onclick="pjDispatchFilterSet('${k}')">${labels[k]}</button>`).join('')}</div><div class="stack" style="margin-top:12px">${list.map(x=>`<button class="btn ${q&&x.id===q.id?'primary':''}" onclick="pjDispatchSelect('${x.id}')">${x.wi} · ${labels[pjProposalState(x)]}</button>`).join('')||'<div class="empty">当前没有这类提案。</div>'}</div>`)}${card('历史提案',pjTable(['工作项','处理','原因'],pjProposals.filter(x=>x.p===p.id&&pjProposalState(x)!=='PROPOSED').map(x=>`<tr><td>${x.wi}</td><td>${labels[pjProposalState(x)]}</td><td>${pjEsc(x.reason)}${x.guards.map(g=>`<div>G${g}：${pjGuards[g-1]}</div>`).join('')}</td></tr>`).join('')))}</div><div class="c8 stack">${q?pjDispatchDetail(p,q):card('提案详情','<div class="empty">选择一个提案查看推荐人、评分与护栏。主管只在进行中的项目为就绪工作项产生提案。</div>')}${card('自动派单护栏 G1–G9',`<div class="stack small">${pjGuards.map((text,i)=>`<div><b>G${i+1}</b> · ${text}</div>`).join('')}</div>`,{icon:'shield-check'})}</div></div>`;}
function pjDispatchDetail(p,q){const w=pjWork.find(w=>w.id===q.wi),pending=pjProposalState(q)==='PROPOSED',mins=Math.max(0,Math.ceil((q.expires-Date.now())/60000));return card('提案 '+q.id,`<div class="row wrap">${p.lead?who(p.lead):'<span>系统评分</span>'}<span class="badge b-info">${p.lead?'主管 Agent 提案':'系统评分'}</span>${pending?`<span class="badge b-warn">剩余 ${mins} 分钟</span>`:''}</div><p><a href="#/workitem/${w.id}"><b>${w.id} · ${pjEsc(w.t)}</b></a> · ${pjType[w.type]} · ${pjRisk[w.risk]}风险</p><p class="small">必需技能：${w.type==='DOC'?'文档、接口说明':w.id==='BIL-139'?'金额计算、边界测试':'接口实现、字段映射'} · 当前状态 ${S(w.s)}</p><div class="note info">推荐 ${PEOPLE[q.chosen].n} · ${q.chosen==='bo'?'82.60':'已处理快照'} 分。${pjEsc(q.reason)}</div>${q.guards.map(g=>`<div class="note warn">G${g} · ${pjGuards[g-1]}</div>`).join('')}${pjTable(['排名 / 候选','总分','技能 35%','首次验收 30%','成本 15%','负载 15%','多样性 5%'],pjScores.map((s,i)=>{const score=s.parts.reduce((n,v,j)=>n+v*[.35,.30,.15,.15,.05][j],0);return `<tr><td>${i+1} · ${who(s.key)}${OR(s.key)}</td><td>${score.toFixed(2)}</td>${s.parts.map((v,j)=>`<td title="${pjEsc(s.raw[j])}">${v}%<div class="progress"><i style="width:${v}%"></i></div><div class="muted xs">${s.raw[j]}</div></td>`).join('')}</tr>`;}).join(''))}<details><summary>不合格候选</summary><p class="small">Ada：活跃分派 3/3，达到并行上限（E8）。Echo：2/2 满载（E8）。Cy：没有执行者角色且已崩溃（E1 / E2）。Gale：孤儿，编制授权已到期（E12）。Atlas：不具执行者绑定，且主管自动派单不能推荐自身。</p></details><details><summary>复算说明</summary><p class="small">技能 35% + 同类型 90 天平滑首次验收 30% + 合格候选成本归一 15% + 当前负载 15% + 近 24 小时轮换 5%。分量取 0–10000 基点，得分四舍五入两位。</p><p class="code">scoring_version=s1 · inputs_digest=演示快照，无真实摘要</p><p class="muted xs">评分输入为演示快照；负载与成员表一致。Bo 总分 82.60，与主文件收件箱一致；满载候选先排除，再做成本归一。</p></details><div class="row wrap" style="margin-top:16px">${pjButton('确认派给 '+PEOPLE[q.chosen].n,`pjDispatchConfirm('${q.id}')`,'primary',!pending||pjReadonly(p)||w.s!=='READY',!pending?'已处理或过期，不能再次确认':w.s!=='READY'?'工作项不再就绪':'')}${pjButton('改派',`pjDispatchAction('${q.id}','override')`,'',!pending||pjReadonly(p))}${pjButton('驳回',`pjDispatchAction('${q.id}','reject')`,'danger',!pending||pjReadonly(p))}</div><p class="muted xs">派单只分配执行工作，不授予裁决权。你以 work_item_assign 权限确认；分派前重新核对状态。</p>`,{icon:'split'});}
function pjDispatchRender(){document.getElementById('pj-dispatch-body').innerHTML=pjDispatchBody(pjProject(pjCurrent));pjIcons();}
function pjDispatchFilterSet(state){pjDispatchFilter=state;pjDispatchId='';pjDispatchRender();}
function pjDispatchSelect(id){pjDispatchId=id;pjDispatchRender();}
function pjDispatchConfirm(id){const q=pjProposals.find(q=>q.id===id),w=pjWork.find(w=>w.id===q.wi),p=pjProject(q.p);if(pjProposalState(q)!=='PROPOSED')return toast('提案已被处理或已过期，请刷新。');if(pjReadonly(p)||w.s!=='READY')return toast('工作项不再就绪，不能分派。');q.state='APPLIED';q.reason='Morgan 确认派给 '+PEOPLE[q.chosen].n;w.who=q.chosen;w.s='CLAIMED';pjEvent(p,q.reason+' · '+w.id);pjDispatchRender();toast('派单已确认（演示），执行仍须通过项目闸门');}
function pjDispatchAction(id,kind){const q=pjProposals.find(q=>q.id===id),p=pjProject(q.p);pjModal(kind==='override'?'改派工作项':'驳回提案',`${kind==='override'?pjSelect('执行者（人与 Agent）','pj-assignee',p.members.filter(k=>k==='chen'||PEOPLE[k].role==='Agent 执行者'&&PEOPLE[k].origin!=='orphan').map(k=>[k,PEOPLE[k].n+' · '+PEOPLE[k].role]),'chen'):''}${pjField('理由（必填）','pj-reason')}<div class="note ${kind==='reject'?'danger':'warn'}">${kind==='override'?'人工改派将在 24 小时内触发 G8 护栏，防止自动策略覆盖你的意图。':'驳回仅关闭本提案，不会取消工作项。'}</div>`,pjButton('取消','closeModal()')+pjButton('确认',`pjDispatchActionSave('${id}','${kind}')`,kind==='reject'?'danger':'primary'));}
function pjDispatchActionSave(id,kind){const q=pjProposals.find(q=>q.id===id),p=pjProject(q.p),w=pjWork.find(w=>w.id===q.wi);if(pjReadonly(p)||pjProposalState(q)!=='PROPOSED')return pjError('提案已被处理或过期，请刷新。');if(!pjVal('pj-reason'))return pjError('请填写理由。');if(kind==='override'){if(w.s!=='READY')return pjError('工作项不再就绪，请刷新。');const k=pjVal('pj-assignee');if(!p.members.includes(k))return pjError('请选择项目内执行者。');w.who=k;w.s='CLAIMED';q.chosen=k;q.state='OVERRIDDEN';q.guards=[8];}else q.state='REJECTED';q.reason='Morgan：'+pjVal('pj-reason');pjEvent(p,'处理派单提案 '+q.id);closeModal();pjDispatchRender();toast('提案已处理（演示）');}

/* 主文件约定的两个创建入口 */
function newProjectWizard(){pjWizard={step:0,name:'',code:'',client:'',description:'',target:'',contact:'lee',receives:true,accepts:true,members:['morgan'],lead:'',budget:'800.00',notify:'80',repo:'',ai:true};try{const saved=JSON.parse(sessionStorage.getItem('pj-project-draft')||'null');if(saved)pjWizard={...pjWizard,...saved};}catch(pjIgnored){}pjWizardRender();}
function pjWizardRender(){const d=pjWizard,labels=['基本信息','开口与联系人','团队与模式','预算','确认'];let body='';
 if(d.step===0)body=`${pjField('项目名称（必填，最多 200 字）','pj-w-name',d.name,'text','maxlength="200"')}${pjField('项目代号（必填，创建后不可修改）','pj-w-code',d.code)}<p class="muted xs">大写字母开头，2–16 位，仅大写字母、数字、连字符；团队内唯一。</p>${pjField('甲方分组（可空）','pj-w-client',d.client)}${pjField('简介','pj-w-description',d.description,'text','maxlength="2000"')}${pjField('目标交付日（可空，不早于今天）','pj-w-target',d.target,'date')}`;
 if(d.step===1)body=`${pjSelect('来源开口','pj-w-channel',[['门户','门户'],['邮件','邮件'],['API','API']],d.channel||'门户')}${pjSelect('主联系人（可稍后补）','pj-w-contact',[['','稍后配置'],['lee','Lee · 甲方联系人']],d.contact)}<label class="row"><input type="checkbox" id="pj-w-receives" ${d.receives?'checked':''}>接收交付通知</label><label class="row"><input type="checkbox" id="pj-w-accepts" ${d.accepts?'checked':''} disabled>主联系人可签收（强制开启）</label><div class="note warn">没有可签收联系人将无法正式交付；甲方只通过开口提交、澄清、验收，不加入乙方执行团队。</div>`;
 if(d.step===2)body=`<div class="note info">你将成为本项目交付负责人。</div><div class="grid g12">${Object.keys(PEOPLE).filter(k=>PEOPLE[k].k!=='c').map(k=>`<label class="c6 row"><input type="checkbox" id="pj-w-member-${k}" ${d.members.includes(k)?'checked':''} ${k==='morgan'?'disabled':''}>${who(k)}${OR(k)}</label>`).join('')}</div>${pjSelect('主管 Agent','pj-w-lead',[['','未设置'],['lead','Atlas · 主管 Agent']],d.lead)}<label class="stack small">团队模式<select style="${pjInputStyle}" disabled><option>混编（默认）</option><option disabled>全自治（需创建后满足 P1–P5）</option></select></label><div class="muted xs">新项目默认混编；全 Agent 的成员组合也可使用混编模式。全自治需创建后满足 P1–P5 并由人重新认证切换。</div>`;
 if(d.step===3)body=`${pjField('预算上限（美元，可空 = 不限）','pj-w-budget',d.budget,'number','min="0.01" step="0.01"')}${pjField('通知阈值（50–95）','pj-w-notify',d.notify,'number','min="50" max="95"')}${pjField('主仓库远程地址（可空，不得含凭证）','pj-w-repo',d.repo)}<p class="muted xs">默认分支 main，保护 main；每台机器上的本地路径在机器页配置。</p><label class="row"><input type="checkbox" id="pj-w-ai" ${d.ai?'checked':''}>门户展示 AI 协作标签</label><div class="note info">80% 通知、100% 暂停新执行；不限预算不可启用全自治。</div>`;
 if(d.step===4)body=`<dl class="kv"><dt>项目</dt><dd>${pjEsc(d.name)} · ${pjEsc(d.code)}</dd><dt>甲方分组</dt><dd>${pjEsc(d.client||'未分组')}</dd><dt>开口 / 联系人</dt><dd>${pjEsc(d.channel)} · ${d.contact?'Lee':'尚未配置'}</dd><dt>团队</dt><dd>${d.members.map(k=>PEOPLE[k].n).join('、')} · 混编</dd><dt>主管</dt><dd>${d.lead?PEOPLE[d.lead].n:'未设置'}</dd><dt>预算</dt><dd>${d.budget?money(Number(d.budget)):'不限'} · ${d.notify}% 通知</dd><dt>仓库</dt><dd>${pjEsc(d.repo||'尚未配置')}</dd><dt>门户 AI 标签</dt><dd>${d.ai?'展示':'隐藏'}</dd></dl><div class="note info">正式产品会一次创建项目、档案、默认频道与角色绑定。当前仅在本脚本内创建演示记录；刷新恢复。</div>`;
 pjModal('新建项目 · '+(d.step+1)+'/5',`<div class="row wrap">${labels.map((t,i)=>`<span class="chip ${i===d.step?'on':''}">${i+1} ${t}</span>`).join('')}</div><div class="stack">${body}</div>`,pjButton('取消','closeModal()')+(d.step?pjButton('上一步','pjWizardMove(-1)'):'')+pjButton(d.step===4?'创建项目':'下一步',d.step===4?'pjWizardCreate()':'pjWizardMove(1)','primary').replace('<button ', '<button id="pj-wizard-next" '),true);
 const modal=document.getElementById('modal');if(modal){modal.querySelectorAll('input,select').forEach(el=>{el.addEventListener('input',pjWizardUpdate);el.addEventListener('change',pjWizardUpdate);});}pjWizardUpdate();
}
function pjWizardCapture(){const d=pjWizard;if(d.step===0){d.name=pjVal('pj-w-name');d.code=pjVal('pj-w-code');d.client=pjVal('pj-w-client');d.description=pjVal('pj-w-description');d.target=pjVal('pj-w-target');}if(d.step===1){d.channel=pjVal('pj-w-channel');d.contact=pjVal('pj-w-contact');d.receives=document.getElementById('pj-w-receives').checked;d.accepts=true;}if(d.step===2){d.members=Object.keys(PEOPLE).filter(k=>{const e=document.getElementById('pj-w-member-'+k);return e&&e.checked;});d.lead=pjVal('pj-w-lead');}if(d.step===3){d.budget=pjVal('pj-w-budget');d.notify=pjVal('pj-w-notify');d.repo=pjVal('pj-w-repo');d.ai=document.getElementById('pj-w-ai').checked;}}
function pjWizardUpdate(){pjWizardCapture();const d=pjWizard;let error='';if(d.step===0){if(!d.name||d.name.length>200)error='下一步前请填写项目名称（最多 200 字）。';else if(!/^[A-Z][A-Z0-9-]{1,15}$/.test(d.code))error='下一步前请填写合法的 2–16 位大写代号。';else if(pjProjects.some(p=>p.code===d.code))error='此代号已存在，请修改。';}if(d.step===2&&d.lead&&!d.members.includes(d.lead))error='请将主管 Agent 加入项目成员。';if(d.step===3){if(d.budget&&(!/^\d+(\.\d{1,2})?$/.test(d.budget)||Number(d.budget)<=0))error='预算须为正数且最多两位小数，或留空表示不限。';else if(!Number.isInteger(Number(d.notify))||Number(d.notify)<50||Number(d.notify)>95)error='通知阈值须为 50–95 的整数。';else if(d.repo&&(!/^(https:\/\/|ssh:\/\/|git@)[^\s]+$/.test(d.repo)||/\/\/[^/]*:[^/@]+@/.test(d.repo)||/^https:\/\/[^/]*@/.test(d.repo)))error='仓库地址格式无效或含凭证。';}const next=document.getElementById('pj-wizard-next');if(next)next.disabled=!!error;const hint=document.getElementById('pj-modal-error');if(hint)hint.textContent=error;try{sessionStorage.setItem('pj-project-draft',JSON.stringify(d));}catch(pjIgnored){}return !error;}
function pjWizardMove(delta){pjWizardCapture();const d=pjWizard;if(delta>0){if(d.step===0){if(!d.name||d.name.length>200||! /^[A-Z][A-Z0-9-]{1,15}$/.test(d.code))return pjError('请填写项目名称与合法代号。');if(pjProjects.some(p=>p.code===d.code||p.name===d.name&&p.client===d.client))return pjError('代号已存在，或同甲方下名称重复。');const today=new Date();const date=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');if(d.target&&d.target<date)return pjError('目标交付日不能早于今天。');}if(d.step===2&&d.lead&&!d.members.includes(d.lead))return pjError('主管必须同时加入本项目成员。');if(d.step===3){if(d.budget&&(!/^\d+(\.\d{1,2})?$/.test(d.budget)||Number(d.budget)<=0)||!Number.isInteger(Number(d.notify))||Number(d.notify)<50||Number(d.notify)>95)return pjError('预算必须为正数且最多两位小数，阈值为 50–95 的整数。');if(d.repo&&(! /^(https:\/\/|ssh:\/\/|git@)[^\s]+$/.test(d.repo)||/\/\/[^/]*:[^/@]+@/.test(d.repo)))return pjError('远程地址必须为 HTTPS、SSH 或 git@ 地址，且不得含凭证。');}}d.step+=delta;try{sessionStorage.setItem('pj-project-draft',JSON.stringify(d));}catch(pjIgnored){}pjWizardRender();}
function pjWizardCreate(){const d=pjWizard;if(pjProjects.some(p=>p.code===d.code))return pjError('代号已存在，请返回修改。');const id='pj-new-'+(pjProjects.length+1),p={id,name:d.name,code:d.code,stage:'INTAKE',mode:'HYBRID',budget:[0,d.budget?Number(d.budget):Infinity],acc:[0,0],lead:d.lead||null,client:(d.contact?'Lee':'未配置联系人')+' · '+d.channel,health:'ok',members:[...d.members],policy:'MANUAL',parallel:3,description:d.description,target:d.target,ai:d.ai,roles:false,portal:{titles:true,evidence:true,notes:true,milestones:true},contacts:!!d.contact,repo:d.repo,notify:Number(d.notify),events:[],version:1};pjProjects.push(p);PROJECTS.push({...p,budget:[...p.budget],acc:[...p.acc]});try{sessionStorage.removeItem('pj-project-draft');}catch(pjIgnored){}closeModal();go('project/'+id);toast('项目已创建（内存演示），默认频道仅为模拟');}
function newWorkItem(){const p=pjProject(pjNewItemProject)||pjProject('p1');if(pjReadonly(p))return toast('项目只读，不能新建工作项');pjNewItemProject=p.id;pjModal('新建工作项 · '+p.code,`<div class="grid g12"><div class="c6 stack">${pjField('标题（必填）','pj-wi-title')}${pjSelect('类型','pj-wi-type',Object.keys(pjType).map(k=>[k,pjType[k]]),'FEATURE')}${pjSelect('风险','pj-wi-risk',Object.keys(pjRisk).map(k=>[k,pjRisk[k]]),'LOW')}${pjSelect('所属需求','pj-wi-requirement',[['','不关联需求'],...pjRequirements.filter(r=>r.p===p.id).map(r=>[r.id,r.id+' · '+r.title])],'')}<div class="stack small"><b>关联验收标准（仅 R-12 有明细）</b>${p.id==='p1'?pjCriteria.map(c=>`<label class="row"><input type="checkbox" id="pj-wi-c-${c.code}">${c.code} · ${c.text}</label>`).join(''):'<span class="muted">本项目暂无需求标准明细。</span>'}</div></div><div class="c6 stack"><b>依赖（必须是同项目工作项）</b>${pjWork.filter(w=>w.p===p.id&&w.s!=='CANCELLED').map(w=>`<label class="row small"><input type="checkbox" id="pj-wi-dep-${w.id}">${w.id} · ${w.t}</label>`).join('')}${pjField('估算（分钟，非负整数）','pj-wi-estimate','60','number','min="0" step="1"')}${pjSelect('派单方式','pj-wi-dispatch',[['proposal','主管 / 系统评分提案'],['manual','你手动分派'],['unassigned','暂不派单']],'proposal')}${pjSelect('执行者（手动分派时必选）','pj-wi-assignee',[['','请选择'],...p.members.filter(k=>k==='chen'||PEOPLE[k].role==='Agent 执行者'&&PEOPLE[k].origin!=='orphan').map(k=>[k,PEOPLE[k].n+' · '+PEOPLE[k].role])],'')}<div class="note info">未满足的依赖会使工作项阻塞。新建不代表执行已开始；主管仅在项目进行中对就绪项生成提案。</div></div></div>`,pjButton('取消','closeModal()')+pjButton('创建工作项','pjWorkItemCreate()','primary'),true);}
function pjWorkItemCreate(){const p=pjProject(pjNewItemProject),title=pjVal('pj-wi-title'),req=pjVal('pj-wi-requirement'),estimate=Number(pjVal('pj-wi-estimate')),mode=pjVal('pj-wi-dispatch'),assignee=pjVal('pj-wi-assignee');if(pjReadonly(p))return pjError('项目只读。');if(!title||title.length>500||!Number.isInteger(estimate)||estimate<0)return pjError('请填写标题（最多 500 字）与非负整数估算。');const criteria=pjCriteria.filter(c=>{const e=document.getElementById('pj-wi-c-'+c.code);return e&&e.checked;});if(criteria.length&&req!=='R-12')return pjError('所选验收标准属于 R-12，请修改所属需求或取消标准选择。');if(mode==='manual'&&!assignee)return pjError('手动派单需选择执行者。');const deps=pjWork.filter(w=>{const e=document.getElementById('pj-wi-dep-'+w.id);return e&&e.checked;});const blocked=deps.some(w=>w.s!=='ACCEPTED'),id=p.code+'-'+(Math.max(0,...pjWork.filter(w=>w.p===p.id).map(w=>Number(w.id.split('-').pop())||0))+1),r=pjRequirements.find(r=>r.id===req);const w={id,t:title,p:p.id,type:pjVal('pj-wi-type'),risk:pjVal('pj-wi-risk'),s:blocked?'BLOCKED':mode==='manual'?'CLAIMED':'READY',who:mode==='manual'?assignee:null,l:0,br:0,cost:0,requirement:req||'—',estimate,baseline:r?'v'+r.version:'—',criteria:criteria.map(c=>c.code),dependencies:deps.map(w=>w.id),stale:false};pjWork.push(w);WI.push({...w});criteria.forEach(c=>c.items.push(id));pjEvent(p,'创建工作项 '+id);closeModal();if(document.getElementById('pj-project-body'))pjOpenTab(2);else go('project/'+p.id);toast('已创建 '+id+(mode==='proposal'?'；派单提案等待主管 / 系统生成':''));}
